import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let bs = [true, false, true]
    let r = bs.iterator().reduce(|p, q| p || q)
    match r {
        Some(v) => { if v { io.println("bool-reduce-ok") } else { io.println("bool-reduce-bad") } }
        None => { io.println("bool-reduce-none") }
    }

    let f = bs.iterator().find(|x| !x)
    match f {
        Some(v) => { if v { io.println("bool-find-bad") } else { io.println("bool-find-ok") } }
        None => { io.println("bool-find-none") }
    }

    let rs = ['a', 'b', 'c']
    let g = rs.iterator().find(|c| c == 'b')
    match g {
        Some(v) => { if v == 'b' { io.println("rune-find-ok") } else { io.println("rune-find-bad") } }
        None => { io.println("rune-find-none") }
    }

    let rc = rs.iterator().count()
    if rc == 3 { io.println("rune-count-ok") } else { io.println("rune-count-bad") }

    return Ok(())
}
